<?php require "db.php";$u=require_role("recruiter");$d=input();$id=(int)($d["id"]??0);$status=$d["status"]??"";if(!in_array($status,["Shortlisted","Rejected","Applied"],true))done(["success"=>false,"message"=>"Invalid status."]);$s=$pdo->prepare("UPDATE applications a JOIN jobs j ON j.id=a.job_id SET a.status=? WHERE a.id=? AND j.recruiter_id=?");$s->execute([$status,$id,$u["id"]]);done(["success"=>$s->rowCount()>0,"message"=>"Application status updated."]);?>